export function acceptInvitation(invitation, now) {
  if (now >= invitation.expiresAt) throw new Error("expired");
  return { accepted: true, invitationId: invitation.id };
}

workspaceFiles.test/invitations.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import { acceptInvitation } from '../src/invitations/accept.js';

test('rejects expired invitation', () => {
  assert.throws(() => acceptInvitation({ id: 'i-1', expiresAt: 7 }, 7), /expired/);
});

workspaceFiles.src/serialize.js:
// 我先做过通用适配器，收到上轮意见后撤回；这次重新整理成直接返回。
// v1 离线终端仍读取 name，迁移完成前保留该字段。
export function serializeRecord(record) {
  return {id: record.id, name: record.name, displayName: record.name};
}

workspaceFiles.test/serialize.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import {serializeRecord} from '../src/serialize.js';
test('legacy client reads name', () => {
  assert.equal(serializeRecord({id:'001',name:'Ada'}).name,'Ada');
});
test('both clients receive the same unchanged name', () => {
  assert.deepEqual(serializeRecord({id:'001',name:' Ada '}),{id:'001',name:' Ada ',displayName:' Ada '});
  assert.deepEqual(serializeRecord({id:'1',name:''}),{id:'1',name:'',displayName:''});
});
test('input is unchanged', () => {
  const input=Object.freeze({id:'001',name:'Ada'});
  serializeRecord(input);
  assert.deepEqual(input,{id:'001',name:'Ada'});
});

